try (Scanner sc = new Scanner(new FileReader("students.txt")); PrintWriter out = new PrintWriter("failed.txt")) {
  int sum = 0, n = 0;
  while (sc.hasNext()) { String name = sc.next(); int m = sc.nextInt(); sum += m; n++; if (m < 50) out.println(name); }
  System.out.println(n == 0 ? 0 : (double) sum / n);
} catch (IOException e) { System.out.println(e.getMessage()); }
